$('run').onclick=async()=>{if(busy||!ui.ready)return;$('error').hidden=true;readCustom();const issues=teams.flatMap((t,i)=>teamIssues(t).map(s=>'AB'[i]+': '+s));if(issues.length){showView('result');fail(issues.join(' '));return}for(const input of document.querySelectorAll('input:not([type=file]):not(:disabled)')){if(input.closest('#characterPicker'))continue;if(!input.checkValidity()){const pane=input.closest('.view-pane');if(pane)showView(pane.id.replace('view-',''));let p=input.parentElement;while(p){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}input.reportValidity();return}}const submitted=settings();busy=true;$('run').disabled=true;$('run').textContent='계산 중…';$('download').disabled=true;showView('result');$('results').hidden=true;$('empty').hidden=false;$('empty').innerHTML='<div class="empty-icon busy">A ↔ B</div><strong>두 편성을 같은 조건으로 계산하고 있어요.</strong><p>다른 탭에서 설정을 확인할 수 있습니다. 변경한 설정은 다음 실행에 적용됩니다.</p>';$('status').textContent='계산 준비 중…';const start=Date.now();const timer=setInterval(()=>$('status').textContent=`계산 중 · ${Math.floor((Date.now()-start)/1000)}초 경과`,1000);try{const response=await fetch('/simulate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(submitted)});const r=await response.json();if(!response.ok)throw Error(r.error||'계산에 실패했습니다.');lastResult=r;render(r);$('status').textContent=`${r.settings.duration}초 전투 · ${((Date.now()-start)/1000).toFixed(1)}초 소요 · 계산 완료 · 결과 내보내기로 내려받기`;if(JSON.stringify(submitted)!==JSON.stringify(settings()))$('status').textContent+=' · 실행 중 설정 변경됨: 이전 조건의 결과입니다.';}catch(e){fail(e.message);$('empty').hidden=true;$('status').textContent='설정을 확인한 뒤 다시 실행하세요.'}finally{clearInterval(timer);busy=false;$('run').disabled=false;$('run').textContent='다시 비교 실행';if(lastResult)$('download').disabled=false}};
