// Existing characters have resource-ID-matched local portraits. Trial characters stay distinct.
function addPortrait(button,name){
 const box=document.createElement('span');box.className='portrait-box';
 const url=name===CUSTOM?null:charByName(name)?.portrait;
 if(url){const img=document.createElement('img');img.src=url;img.alt='';img.width=64;img.height=64;img.loading='lazy';img.decoding='async';img.onerror=()=>{img.remove();box.textContent='?';box.classList.add('portrait-fallback')};box.append(img)}
 else {box.classList.add('portrait-fallback');box.textContent=name===CUSTOM?'시험':'?'}
 button.querySelector('strong').before(box);button.classList.add('has-portrait');
}
