// Favorite items are per squad; missing settings preserve older drafts' stage-3 default.
function hasFavorite(n){return n!==CUSTOM&&!!charByName(n)?.has_favorite}
function favoriteOn(t,n){return t.favorites?.[n]!==false}
function favoriteDifferences(){return teams[0].members.filter(n=>hasFavorite(n)&&teams[1].members.includes(n)&&favoriteOn(teams[0],n)!==favoriteOn(teams[1],n))}
const summaryBeforeFavorites=updateSummary;
updateSummary=function(){summaryBeforeFavorites();if(teams.length&&favoriteDifferences().length)$('runSummary').textContent+=' · 애장품 설정 다름'};
const teamsBeforeFavorites=drawTeams;
drawTeams=function(){
 for(const t of teams)t.favorites=Object.fromEntries(t.members.filter(hasFavorite).map(n=>[n,favoriteOn(t,n)]));
 teamsBeforeFavorites();
 document.querySelectorAll('[data-pick]').forEach(b=>{
  const [i,j]=b.dataset.pick.split(':').map(Number),n=teams[i].members[j];if(!hasFavorite(n))return;
  const on=favoriteOn(teams[i],n),row=document.createElement('div');row.className='favorite-setting';
  row.innerHTML=`<span>애장품 <small>${on?'3단계':'일반 스킬'}</small></span><button type="button" role="switch" aria-checked="${on}" aria-label="${'AB'[i]} ${esc(n)} 애장품" data-favorite="${i}:${j}"><i></i>${on?'ON':'OFF'}</button>`;
  b.after(row);
 });
 const changes=favoriteDifferences().map(n=>`${n} 애장품 ${favoriteOn(teams[0],n)?'ON':'OFF'} → ${favoriteOn(teams[1],n)?'ON':'OFF'}`);
 if(changes.length){const same=teams[0].members.every((n,j)=>n===teams[1].members[j])&&teams[0].no_burst===teams[1].no_burst&&teams[0].every3===teams[1].every3;$('teamDiff').textContent=(same?'':$('teamDiff').textContent+' / ')+changes.join(' / ')}
};
